window.__CSE391_SEARCH__ = [{"t":"Trang chủ","k":"Trang","u":"index.html","x":"Học làm frontend hiện đại cùng AI — từ HTML5 tới dự án thật — HTML5 • CSS3 • JavaScript ES6+ • Bootstrap 5"},{"t":"Giới thiệu khoá học","k":"Trang","u":"gioi-thieu.html","x":"Sứ mệnh, đối tượng, bộ công cụ và câu hỏi thường gặp."},{"t":"Lộ trình 8 tuần","k":"Trang","u":"lo-trinh.html","x":"Chào mừng & AI-Accelerated Workflow: Bản đồ công cụ AI, quy trình 4 bước Define → Draft → Analyze → Refine, thiết lập môi trường và giới thiệu dự án Highland Hospital. | Prompt Engineering cho Frontend: Giải phẫu một prompt tốt, prompt cho HTML/CSS, cho JavaScript, cho debug và buổi workshop cắt giao diện bằng prompt. | HTML5 — Chuẩn ngữ nghĩa & Cấu trúc trang: Cấu trúc tài liệu chuẩn, thẻ semantic & SEO, Forms và input hiện đại, bảng biểu, hình ảnh và SVG. | CSS3 — Nền tảng & Tư duy dàn trang: Selectors và Specificity, Box Model, màu sắc — typography — CSS Variables, đơn vị đo tương đối. | CSS Layout — Flexbox & Grid: Flexbox căn bản và nâng cao, CSS Grid, cách chọn đúng công cụ cho từng loại layout. | Responsive Web Design & Animation: Media Queries và breakpoints, Mobile-First workflow, hình ảnh — typography linh hoạt, Transitions & Keyframes. | Bootstrap 5 — Grid & Utilities: Cài đặt Bootstrap qua CDN, hệ thống 12 cột, utility Spacing/Colors/Typography, Buttons/Badges/Alerts. | Bootstrap 5 — Components: Navbar responsive có hamburger, Cards & List group, Forms & Validation, Modal/Offcanvas/Accordion. | JavaScript ES6+ — Cú pháp & Dữ liệu: let/const, Template Literals, Arrow functions, Destructuring, Array Methods cốt lõi, Object & JSON. | DOM & Event Handling: Truy vấn và thao tác DOM, sự kiện & delegation, form validation phía client, localStorage. | Async JavaScript & API: Fetch API / Async-Await, mock REST API, trạng thái Loading & Error, luồng đặt lịch đa bước. | Dự án Highland Hospital & Component Thinking: Tổng quan dự án và đọc Figma, dựng Landing Page, tương tác JavaScript, Admin Dashboard, tối ưu hiệu năng và deploy. | Module bổ trợ — Prompt Engineering cho Frontend: Bộ prompt mẫu chuẩn: phân tích thiết kế Figma, sinh code Bootstrap 5 từ đặc tả, lab Figma → Bootstrap."},{"t":"Dự án tốt nghiệp","k":"Trang","u":"du-an.html","x":"Highland Hospital Web Portal — Landing Page, đặt lịch khám, Admin Dashboard."},{"t":"Từ điển thuật ngữ","k":"Trang","u":"tu-dien.html","x":"Toàn bộ thuật ngữ tiếng Anh kèm nghĩa tiếng Việt."},{"t":"Buổi 01 · Chào mừng — vì sao Frontend cần AI","k":"Buổi học","u":"lessons/buoi-01.html","x":"Nghề frontend gồm hai việc rất khác nhau: phán đoán và sản xuất. AI đang cực giỏi ở việc thứ hai. Bài mở màn xác lập ranh giới \"bạn giữ — AI làm\" và cho bạn thấy mình sẽ xây gì. — Mục tiêu bài học · Nghề frontend đã dịch chuyển · Một ngày làm việc thực tế · Những việc AI không làm thay bạn · Bốn trụ cột của khoá học · Dự án bạn sẽ xây: Highland Hospital Web Portal · Khoá học dành cho ai · Cách học","q":"Theo bài học, hai hoạt động cốt lõi của nghề frontend là gì? Đâu là việc AI KHÔNG làm thay bạn? Dự án xuyên suốt của khoá học là gì? Thói quen học nào được bài này khuyến nghị?"},{"t":"Buổi 02 · Bản đồ công cụ AI cho Frontend","k":"Buổi học","u":"lessons/buoi-02.html","x":"Bốn nhóm công cụ AI mà frontend developer dùng hằng ngày — chat tổng quát, AI trong editor, design-to-code và AI tìm kiếm — cùng bộ công cụ tối thiểu cho cả khoá. — Mục tiêu bài học · Bốn nhóm công cụ, bốn loại việc · Công cụ nào cho việc nào ở dự án Highland Hospital · Bộ công cụ tối thiểu của khoá học · Thực hành","q":"Bốn nhóm công cụ AI được nêu trong bài là? Theo quy tắc của khoá học, output từ công cụ design-to-code nên được coi là gì? Bộ công cụ TỐI THIỂU của khoá học gồm những gì? Vì sao nên ưu tiên câu trả lời AI có trích nguồn (MDN, caniuse, tài liệu chính thức)?"},{"t":"Buổi 03 · AI-Accelerated Workflow 4 bước","k":"Buổi học","u":"lessons/buoi-03.html","x":"Vòng lặp Define → Draft → Analyze → Refine được dùng cho mọi bài của khoá học. Bài này chỉ rõ vì sao bước 3 mới là bước quyết định chất lượng. — Mục tiêu bài học · Vòng lặp 4 bước · Vì sao bước 3 là bước quan trọng nhất · Một vòng lặp mẫu với Highland Hospital · Thực hành","q":"Thứ tự đúng của AI-Accelerated Workflow là? Vì sao bước Analyze (phân tích & thấu hiểu) được coi là quan trọng nhất? Bản nháp HTML/CSS/JS mà AI trả về ở bước Draft là gì? Ở bước Define, bài học khuyên bạn làm gì trước khi dùng AI?"},{"t":"Buổi 04 · Thiết lập môi trường làm việc","k":"Buổi học","u":"lessons/buoi-04.html","x":"Cài VS Code cùng Live Server, tạo cấu trúc thư mục chuẩn cho Highland Hospital và làm quen bốn tab Chrome DevTools bạn sẽ dùng trong mọi bài sau. — Mục tiêu bài học · Bước 1: Cài VS Code và Live Server · Bước 2: Cấu trúc thư mục dự án · Bước 3: File HTML tối thiểu và chạy thử · Bước 4: Làm quen Chrome DevTools · Thực hành","q":"Vì sao KHÔNG nên mở file HTML bằng double-click (file://) khi học tới Fetch API? Live Server làm một việc rất quan trọng là gì? Tab DevTools nào cho biết trình duyệt đang chạy request API nào? Trong cấu trúc thư mục chuẩn của dự án, dữ liệu mẫu bác sĩ nằm ở đâu?"},{"t":"Buổi 05 · Dự án xuyên suốt: Highland Hospital","k":"Buổi học","u":"lessons/buoi-05.html","x":"Ba trang bạn sẽ xây (Landing Page, đặt lịch, Admin Dashboard), bộ dữ liệu dùng chung và bảng phân công \"chương nào làm phần nào\" của dự án Highland Hospital. — Mục tiêu bài học · Bệnh viện Highland là ai? · Ba trang bạn sẽ xây · Dữ liệu mẫu dùng chung · Mỗi chương đóng góp gì · Một prompt khởi động dự án · Thực hành","q":"Ba trang của dự án tương ứng với ba file nào? Bốn trạng thái lịch hẹn dùng xuyên suốt dự án là? Chương 9–10 đóng góp phần nào cho dự án? Ở chương 10–11, mảng appointments chuyển từ bộ nhớ sang đâu?"},{"t":"Accessibility (a11y) — Khả năng tiếp cận","k":"Thuật ngữ","u":"tu-dien.html#g-A","x":"Để người dùng bàn phím và trình đọc màn hình vẫn dùng được trang web."},{"t":"Accordion — Bảng xếp tầng","k":"Thuật ngữ","u":"tu-dien.html#g-A","x":"Nội dung đóng/mở theo từng mục, dùng cho FAQ."},{"t":"Array methods — Hàm mảng","k":"Thuật ngữ","u":"tu-dien.html#g-A","x":"map / filter / reduce — cách hiện đại thay cho vòng for thủ công."},{"t":"Arrow function — Hàm mũi tên","k":"Thuật ngữ","u":"tu-dien.html#g-A","x":"Cú pháp rút gọn (a, b) => a + b, phổ biến trong callback."},{"t":"Async / await — Bất đồng bộ","k":"Thuật ngữ","u":"tu-dien.html#g-A","x":"Cú pháp giúp code gọi API đọc như code tuần tự."},{"t":"Bootstrap grid — Hệ thống cột Bootstrap","k":"Thuật ngữ","u":"tu-dien.html#g-B","x":"12 cột với breakpoint sm / md / lg / xl / xxl."},{"t":"Box model — Mô hình hộp","k":"Thuật ngữ","u":"tu-dien.html#g-B","x":"Cách trình duyệt đóng gói mọi phần tử: content → padding → border → margin."},{"t":"Breakpoint — Điểm dừng responsive","k":"Thuật ngữ","u":"tu-dien.html#g-B","x":"Bề rộng màn hình tại đó layout đổi (576 / 768 / 992 / 1200 / 1400px trong Bootstrap)."},{"t":"Code completion — Gợi ý code","k":"Thuật ngữ","u":"tu-dien.html#g-C","x":"AI đoán và chèn phần code tiếp theo khi bạn gõ hoặc viết chú thích."},{"t":"Console — Bảng điều khiển","k":"Thuật ngữ","u":"tu-dien.html#g-C","x":"Nơi in lỗi JavaScript và kết quả console.log để thử lệnh trực tiếp."},{"t":"CRUD — Create / Read / Update / Delete","k":"Thuật ngữ","u":"tu-dien.html#g-C","x":"Bốn thao tác dữ liệu cơ bản — Admin Dashboard làm Read + Update."},{"t":"CSS custom property — Biến CSS","k":"Thuật ngữ","u":"tu-dien.html#g-C","x":"Giá trị đặt tên kiểu --color-mint-500, nền tảng của design token."},{"t":"CSS Grid — Layout hai trục","k":"Thuật ngữ","u":"tu-dien.html#g-C","x":"Hệ thống hàng và cột cho layout phức tạp của cả trang."},{"t":"Dashboard — Bảng điều khiển","k":"Thuật ngữ","u":"tu-dien.html#g-D","x":"Trang quản trị có thẻ số liệu (metrics) và bảng dữ liệu để tìm kiếm, lọc, cập nhật."},{"t":"Deployment — Phát hành","k":"Thuật ngữ","u":"tu-dien.html#g-D","x":"Đưa website lên internet: GitHub Pages, Netlify, Vercel."},{"t":"Design token — Token thiết kế","k":"Thuật ngữ","u":"tu-dien.html#g-D","x":"Bảng biến màu, font, khoảng cách trích từ thiết kế để code đồng nhất."},{"t":"Design-to-code — Chuyển thiết kế thành code","k":"Thuật ngữ","u":"tu-dien.html#g-D","x":"Nhận một frame Figma và trả về HTML/CSS tương ứng."},{"t":"DevTools — Công cụ nhà phát triển","k":"Thuật ngữ","u":"tu-dien.html#g-D","x":"Bảng điều khiển của trình duyệt: Elements, Console, Network, Device Toolbar."},{"t":"Draft — Bản nháp","k":"Thuật ngữ","u":"tu-dien.html#g-D","x":"Kết quả AI trả về ở bước Draft — chưa phải code cuối cùng."},{"t":"Event delegation — Ủy quyền sự kiện","k":"Thuật ngữ","u":"tu-dien.html#g-E","x":"Gắn một listener trên phần tử cha để xử lý nhiều phần tử con."},{"t":"Fetch API — Gọi API","k":"Thuật ngữ","u":"tu-dien.html#g-F","x":"Cách chuẩn để trình duyệt xin dữ liệu: fetch(url).then(r => r.json())."},{"t":"file:// protocol — Giao thức file","k":"Thuật ngữ","u":"tu-dien.html#g-F","x":"Cách mở thẳng file trên đĩa; bị trình duyệt chặn khi gọi API."},{"t":"Flexbox — Layout một trục","k":"Thuật ngữ","u":"tu-dien.html#g-F","x":"Model dàn xếp phần tử theo một hàng hoặc một cột, căn chỉnh và chia khoảng cách."},{"t":"Frontend — Giao diện phía client","k":"Thuật ngữ","u":"tu-dien.html#g-F","x":"Phần website chạy trong trình duyệt mà người dùng trực tiếp tương tác: HTML, CSS, JavaScript."},{"t":"In-editor AI — AI trong editor","k":"Thuật ngữ","u":"tu-dien.html#g-I","x":"Công cụ gợi ý code ngay trong file bạn đang mở: GitHub Copilot, Cursor."},{"t":"JSON — Định dạng dữ liệu","k":"Thuật ngữ","u":"tu-dien.html#g-J","x":"Cách mô tả object/mảng để trao đổi dữ liệu giữa code và API."},{"t":"Landing page — Trang chủ giới thiệu","k":"Thuật ngữ","u":"tu-dien.html#g-L","x":"Trang chính của website: hero, dịch vụ, bác sĩ, đánh giá, footer."},{"t":"Live Server — Máy chủ cục bộ khi dev","k":"Thuật ngữ","u":"tu-dien.html#g-L","x":"Extension VS Code chạy HTTP server tại chỗ và tự tải lại trình duyệt khi bạn lưu file."},{"t":"LLM (Large Language Model) — Mô hình ngôn ngữ lớn","k":"Thuật ngữ","u":"tu-dien.html#g-L","x":"Nền tảng của Gemini, Claude, ChatGPT — sinh văn bản và code theo ngữ cảnh bạn đưa."},{"t":"Loading state — Trạng thái đang tải","k":"Thuật ngữ","u":"tu-dien.html#g-L","x":"Skeleton hoặc spinner cho người dùng biết dữ liệu chưa về."},{"t":"localhost — Máy chủ cục bộ","k":"Thuật ngữ","u":"tu-dien.html#g-L","x":"Địa chỉ ngay trên máy bạn, ví dụ http://127.0.0.1:5500."},{"t":"localStorage — Lưu trữ cục bộ","k":"Thuật ngữ","u":"tu-dien.html#g-L","x":"Lưu dữ liệu ngay trong trình duyệt theo từng origin, không cần server."},{"t":"Media query — Truy vấn phương tiện","k":"Thuật ngữ","u":"tu-dien.html#g-M","x":"Áp dụng CSS theo điều kiện màn hình, ví dụ (max-width: 767.98px)."},{"t":"Mock API — API giả lập","k":"Thuật ngữ","u":"tu-dien.html#g-M","x":"Nguồn dữ liệu giả để thử luồng gọi API như hệ thống thật."},{"t":"Modal — Hộp thoại","k":"Thuật ngữ","u":"tu-dien.html#g-M","x":"Lớp phủ chiếm sự chú ý, đóng bằng Escape và aria-label theo bài 08."},{"t":"Navbar / Offcanvas — Thanh điều hướng","k":"Thuật ngữ","u":"tu-dien.html#g-N","x":"Component điều hướng của Bootstrap; Offcanvas là menu trượt trên mobile."},{"t":"preventDefault — Chặn hành vi mặc định","k":"Thuật ngữ","u":"tu-dien.html#g-P","x":"Ngăn form tự submit hoặc link tự điều hướng."},{"t":"Prompt — Câu lệnh gửi cho AI","k":"Thuật ngữ","u":"tu-dien.html#g-P","x":"Mô tả bằng lời nhiệm vụ bạn đưa cho AI, kèm bối cảnh và ràng buộc."},{"t":"Pseudo-class — Lớp giả","k":"Thuật ngữ","u":"tu-dien.html#g-P","x":":hover, :focus, :active, :first-child — chọn trạng thái của phần tử."},{"t":"Refactor — Tái cấu trúc","k":"Thuật ngữ","u":"tu-dien.html#g-R","x":"Sửa code cho dễ đọc, dễ bảo trì mà không đổi hành vi."},{"t":"rem / em — Đơn vị tương đối","k":"Thuật ngữ","u":"tu-dien.html#g-R","x":"rem neo theo cỡ gốc, em neo theo cỡ chữ của phần tử — ưu tiên hơn px."},{"t":"Responsive — Thiết kế thích ứng","k":"Thuật ngữ","u":"tu-dien.html#g-R","x":"Giao diện tự sắp xếp đẹp ở mọi cỡ màn hình, từ 320px tới desktop."},{"t":"Semantic HTML — HTML ngữ nghĩa","k":"Thuật ngữ","u":"tu-dien.html#g-S","x":"Dùng đúng thẻ theo ý nghĩa nội dung (<nav>, <article>) thay vì đổ mọi thứ vào <div>."},{"t":"Spec — Đặc tả","k":"Thuật ngữ","u":"tu-dien.html#g-S","x":"Bản mô tả yêu cầu (layout, component, trạng thái) viết ra trước khi đụng đến AI."},{"t":"Specificity — Độ đặc hiệu","k":"Thuật ngữ","u":"tu-dien.html#g-S","x":"Quy tắc quyết định selector nào thắng khi hai luật xung đột."},{"t":"Technical debt — Nợ kỹ thuật","k":"Thuật ngữ","u":"tu-dien.html#g-T","x":"Code bạn giữ mà không giải thích được — thứ phải trả giá ở lần sửa sau."},{"t":"Template literal — Chuỗi mẫu","k":"Thuật ngữ","u":"tu-dien.html#g-T","x":"Chuỗi trong cặp backtick cho phép nhúng biến và xuống dòng."},{"t":"Transition / Keyframes — Chuyển động","k":"Thuật ngữ","u":"tu-dien.html#g-T","x":"transition cho phản hồi nhỏ, @keyframes cho chuyển động có chủ ý."},{"t":"Viewport — Vùng hiển thị","k":"Thuật ngữ","u":"tu-dien.html#g-V","x":"Phần trang web nhìn thấy được trên màn hình; khai báo bằng <meta name=\"viewport\">."},{"t":"Phân tích yêu cầu — Define","k":"Khái niệm","u":"index.html#workflow","x":"Đọc thiết kế Figma hoặc mô tả, bóc tách cấu trúc khối, liệt kê component và trạng thái tương tác. Viết ra 3–5 câu đặc tả trước khi đụng đến AI."},{"t":"Soạn thảo với AI — Draft","k":"Khái niệm","u":"index.html#workflow","x":"Viết prompt chính xác từ đặc tả: bối cảnh dự án, ràng buộc công nghệ, giá trị thiết kế và định dạng đầu ra. Nhận bản nháp HTML/CSS/JS."},{"t":"Phân tích & thấu hiểu — Analyze","k":"Khái niệm","u":"index.html#workflow","x":"Đọc từng dòng code và trả lời: vì sao dùng thẻ/class này, layout vận hành thế nào, luồng dữ liệu và sự kiện ra sao. Không giải thích được thì không giữ."},{"t":"Tinh chỉnh & tối ưu — Refine","k":"Khái niệm","u":"index.html#workflow","x":"Chỉnh breakpoint, sửa lỗi hiển thị, chuẩn hoá class theo Bootstrap utilities, tách hàm tái sử dụng. Kiểm tra nhiều cỡ màn hình rồi mới coi là xong."},{"t":"Tôi chưa biết gì về lập trình, học được không?","k":"Hỏi đáp","u":"gioi-thieu.html#faq","x":"Được. Điều kiện tiên quyết duy nhất là biết dùng máy tính và gõ phím. Chương 1 và 2 xây nền trước, HTML bắt đầu từ số không ở chương 3."},{"t":"Có bắt buộc phải trả phí công cụ AI không?","k":"Hỏi đáp","u":"gioi-thieu.html#faq","x":"Không. Bản miễn phí của Gemini, ChatGPT hoặc Claude đủ cho 5 buổi đầu và phần lớn khoá. Copilot hay Cursor là điểm cộng, không bắt buộc."},{"t":"Tôi có cần biết React hay framework không?","k":"Hỏi đáp","u":"gioi-thieu.html#faq","x":"Không. Mọi thứ được xây bằng HTML, CSS, JavaScript thuần và Bootstrap 5. Phải tới chương 12 bạn mới làm quen tư duy component và lý do tồn tại của framework."},{"t":"Vì sao trang này chỉ có 5 buổi học?","k":"Hỏi đáp","u":"gioi-thieu.html#faq","x":"Website phát hành theo tiến độ lớp. Năm buổi đầu (toàn bộ Chương 1) đã đầy đủ; chương trình 12 chương / 64 bài được hiển thị trong trang Lộ trình và sẽ mở dần."},{"t":"Mỗi buổi mất bao lâu?","k":"Hỏi đáp","u":"gioi-thieu.html#faq","x":"Khoảng 45–60 phút đọc và làm theo trong buổi, cộng 30–60 phút thực hành ở nhà. Bài nào cũng có checklist để bạn tự kiểm tra."},{"t":"Tiến độ học của tôi được lưu ở đâu?","k":"Hỏi đáp","u":"gioi-thieu.html#faq","x":"Ngay trên trình duyệt của bạn (localStorage). Không có tài khoản, không có server, không có dữ liệu nào được gửi đi."}];